void ProgressiveExtractor::worker_loop(){
    std::cout<<"[Extractor] "<<current_path_<<"\n";
    has_prev_tail_ = false;
    const uint32_t hop = step_ms_.load();   // bar-aligned (or default) for this track
    uint64_t cursor=0;
    while(!cancel_flag_.load() && cursor < duration_ms_){
        auto seg=std::make_unique<StemSegment>();
        if(!extract_segment(cursor, hop, *seg)){
            set_state(ExtractionState::Failed,0.0f); return;
        }
        uint64_t end=std::min(cursor+(uint64_t)hop,(uint64_t)duration_ms_);
        seg->start_ms=cursor; seg->end_ms=end; seg->valid=true;
        store_segment(std::move(seg));
        cursor=end;
        extracted_ms_.store(cursor);
        float prog=(float)cursor/duration_ms_;
        if(state_.load()==ExtractionState::Extracting &&
           cursor>=(uint64_t)(ACTIVATION_SECONDS*1000))
            set_state(ExtractionState::Ready,prog);
        else
            set_state(state_.load(),prog);
        std::cout<<"[Extractor] "<<cursor/1000<<"s / "<<duration_ms_/1000<<"s\n";
    }
    if(!cancel_flag_.load()) set_state(ExtractionState::Complete,1.0f);

