void StemTransport::fill_output(uint32_t nframes,float* out_l,float* out_r,
                                 const std::array<int,N_STEMS>& vols){
    std::memset(out_l,0,nframes*sizeof(float));
    std::memset(out_r,0,nframes*sizeof(float));
    if(mode_.load()!=Mode::Stemming)return;

    // Target gain per stem for this callback. On the first callback after
    // (re)entering Stemming, snap smoothed_gain_ straight to target — nothing
    // was playing before, so there's no discontinuity to declick against.
    // On every later callback, smoothed_gain_ ramps toward target one-pole
    // per sample, so a volume/mute change never produces a hard step.
    float target_gain[N_STEMS];
    for(int s=0;s<N_STEMS;++s) target_gain[s]=(float)vols[s]/100.0f;

    if(!gain_primed_){
        for(int s=0;s<N_STEMS;++s) smoothed_gain_[s]=target_gain[s];
        gain_primed_=true;
    }

