// ── Bar-aligned hop ───────────────────────────────────────────────────────────

uint32_t ProgressiveExtractor::bar_aligned_hop_ms(float bpm){
    if(bpm <= 60.0f || bpm >= 250.0f) return StemSegment::STEP_MS;

    // One 4/4 bar in milliseconds
    const float bar_ms = 60000.0f / bpm * 4.0f;

    // Number of bars whose total length is nearest to the default 7500 ms hop.
    // At least 1 bar; capped so the hop never exceeds CHUNK_SECS*1000 - 500 ms
    // (preserving a minimum 500 ms overlap for a clean crossfade).
    const int max_bars = (int)std::floor(
        (StemSegment::CHUNK_SECS * 1000 - 500) / bar_ms
    );
    const int n_bars   = std::max(1, std::min(max_bars,
        (int)std::round((float)StemSegment::STEP_MS / bar_ms)
    ));
    const uint32_t hop = (uint32_t)std::round((float)n_bars * bar_ms);
    return hop;
}

