def validate_change(section: str, key: str, value) -> tuple[bool, str]:
    if (section, key) in LOCKED:
        return False, f"{section}.{key} is LOCKED"
    if (section, key) in HUMAN_ONLY:
        return False, f"{section}.{key} needs human approval"
    bounds = TUNABLE.get((section, key))
    if bounds is None:
        return False, f"{section}.{key} is not a tunable parameter"
    try:
        v = float(value)
    except (TypeError, ValueError):
        return False, f"{section}.{key}: value {value!r} is not numeric"
    lo, hi = bounds
    if not lo <= v <= hi:
        return False, f"{section}.{key}={v} outside bounds [{lo}, {hi}]"
    return True, "ok"

