def _greedy_order(self, start_idx: int, costs: np.ndarray) -> list[int]:
    ordered = [start_idx]
    remaining = set(range(len(self.tracks))) - {start_idx}
    while remaining:
        current = ordered[-1]
        next_idx = min(remaining, key=lambda j: costs[current, j])
        ordered.append(next_idx)
        remaining.remove(next_idx)
    return ordered

