/// js tick(). slow motion scales how much time is ADDED to the accumulator,
/// never the step size — changing the step would break every solve in the sim
public void Advance(float frameDt)
{
    if (frameDt > 0.05f) frameDt = 0.05f;
    if (frameDt < 0f) frameDt = 0f;

    // hit-stop: a crisp micro-freeze at impact. it counts down in real time
    // and nearly stalls the sim clock while it lasts, so the ball and players
    // hang for a beat — the view keeps rendering, so shake and particles run
    // on and the frozen frame reads as a punch the TimeScale slow-mo eases out
    if (S.HitStop > 0f)
    {
        S.HitStop = Mathf.Max(0f, S.HitStop - frameDt);
        frameDt *= 0.05f;
    }
    if (S.FovKick > 0f) S.FovKick = Mathf.Max(0f, S.FovKick - frameDt * 30f);

    S.TimeScale = SimMath.Damp(S.TimeScale, 1f, 0.03f, frameDt);
    _accum = Mathf.Min(_accum + frameDt * S.TimeScale, Tuning.SimDt * 8f);
    while (_accum >= Tuning.SimDt)
    {
        Step(Tuning.SimDt);
        _accum -= Tuning.SimDt;
    }

