def resolve_includes(body: str, target: str, agent_name: str) -> str:
    """Inline {{include:NAME}} partials. dashboard-logging resolves shell-variant."""
    def sub(m: re.Match) -> str:
        inc = m.group(1)
        if inc == "dashboard-logging":
            inc = f"dashboard-logging.{SHELL_FOR_TARGET.get(target, 'bash')}"
        p = PARTIALS_DIR / f"{inc}.md"
        if not p.exists():
            sys.exit(f"ERROR: {agent_name}: missing partial '{p.name}'")
        return p.read_text(encoding="utf-8").strip()

    result = re.sub(r"\{\{include:([\w.\-]+)\}\}", sub, body)
    leftover = re.search(r"\{\{[^}]*\}\}", result)
    if leftover:
        sys.exit(f"ERROR: {agent_name}: unresolved placeholder {leftover.group(0)}")
    return result

